  /// payments). {@link ecommerce_mall_orders.id}
  ecommerce_mall_order_id String? @db.Uuid

  /// Type of payment method: credit_card, debit_card, digital_wallet,
  /// bank_transfer, cryptocurrency, etc.
  payment_type String

  /// Encrypted payment token or payment method identifier from payment
  /// processor (never store actual card numbers).
  payment_token String

  /// Payment processor provider: stripe, paypal, square, etc.
  payment_provider String

  /// Last four digits of payment method for customer reference (if applicable).
  last_four_digits String?

  /// Payment method brand: visa, mastercard, amex, paypal, etc.
  brand String?

  /// Expiration month for cards (1-12).
  expiration_month Int? @db.Integer

  /// Expiration year for cards (4-digit year).
  expiration_year Int? @db.Integer

  /// Name on billing address for this payment method.
  billing_name String?

  /// Email associated with billing address for this payment method.
  billing_email String?

  /// Whether this is the customer's default payment method for faster checkout.
  is_default Boolean

  /// Whether this payment method has been verified (e.g., through small charge
  /// or verification process).
  is_verified Boolean

  /// Status of payment method verification: pending, verified, failed, expired.
  verification_status String

  /// Payment method status: active, inactive, expired, suspended,
  /// failed_verification.
  status String

  /// Unique fingerprint of payment method for fraud detection and duplicate
  /// prevention.
  fingerprint String?

  /// First line of billing address for this payment method.
  billing_address_line1 String?

  /// Second line of billing address for this payment method.
  billing_address_line2 String?

  /// City of billing address for this payment method.
  billing_city String?

  /// State/province of billing address for this payment method.
  billing_state String?

  /// Postal code of billing address for this payment method.
  billing_postal_code String?

  /// Country code of billing address for this payment method.
  billing_country String?

  /// Timestamp when payment method was added to account.
  created_at DateTime @db.Timestamptz

  /// Timestamp when payment method was last modified.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for audit compliance (financial records
  /// retention).
  deleted_at DateTime? @db.Timestamptz

  /// JSON metadata for additional payment method information (payment
  /// processor specific data).
  metadata String? @db.VarChar(80000)

  //----
  // RELATIONS
  //----
  customer ecommerce_mall_customers @relation(fields: [ecommerce_mall_customer_id], references: [id], onDelete: Cascade)
  order ecommerce_mall_orders? @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)

  ecommerce_mall_transactions ecommerce_mall_transactions[]
  ecommerce_mall_payment_audits ecommerce_mall_payment_audits[]

  @@index([ecommerce_mall_order_id])

  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_customer_id, payment_token], map: "ecommerce_mall_payment_methods_ecommerce_mall_customer_40640f79")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_customer_id, is_default], map: "ecommerce_mall_payment_methods_ecommerce_mall_customer_aee7a8f3")
  @@index([status, is_verified])
  @@index([payment_token(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([billing_name(ops: raw("gin_trgm_ops"))], type: Gin)
