/// Payment dispute and chargeback records for transaction conflicts. Tracks
/// complete dispute lifecycle from customer complaint through resolution,
/// including evidence collection, communication logging, and financial
/// impact tracking. Supports both internal disputes and external chargebacks
/// with comprehensive audit trails for legal compliance and financial
/// reconciliation.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_disputes {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Transaction that is being disputed. {@link ecommerce_mall_transactions.id}
  ecommerce_mall_transaction_id String @db.Uuid

  /// Order associated with disputed transaction. {@link
  /// ecommerce_mall_orders.id}
  ecommerce_mall_order_id String @db.Uuid

  /// Customer who initiated the dispute. {@link ecommerce_mall_customers.id}
  ecommerce_mall_customer_id String @db.Uuid

  /// Seller involved in the dispute. {@link ecommerce_mall_sellers.id}
  ecommerce_mall_seller_id String @db.Uuid

  /// Administrator assigned to handle this dispute. {@link
  /// ecommerce_mall_administrators.id}
  ecommerce_mall_administrator_id String? @db.Uuid

  /// Type of dispute: chargeback, payment_dispute, refund_dispute,
  /// fraud_dispute, billing_error, product_not_received,
  /// product_not_as_described.
  dispute_type String

  /// Source of dispute: customer_service, payment_gateway,
  /// credit_card_company, bank, internal_fraud_detection.
  dispute_source String

  /// Reason code from dispute source: fraud, product_not_received,
  /// product_not_as_described, duplicate_charge, incorrect_amount, other.
  reason_code String

  /// Detailed description of dispute reason from customer or card issuer.
  reason_details String

  /// Dispute status: opened, under_review, evidence_required,
  /// evidence_submitted, won, lost, withdrawn, settled, expired.
  status String

  /// Business workflow status: assigned, investigating, awaiting_response,
  /// escalated, resolved.
  business_status String

  /// Dispute priority level: low, medium, high, critical.
  priority String

  /// Amount being disputed in base currency.
  dispute_amount Float @db.DoublePrecision

  /// ISO currency code for dispute amount.
  currency String

  /// Whether this dispute is related to suspected fraud.
  is_fraud_related Boolean

  /// Whether this is an external chargeback (true) or internal dispute (false).
  is_external Boolean

  /// Payment gateway managing the dispute process (for external disputes).
  payment_gateway String?

  /// Dispute ID from payment gateway or card issuer (external reference).
  gateway_dispute_id String?

  /// Credit card issuer name (for external chargebacks).
  card_issuer String?

  /// Cardholder's statement about the dispute from card issuer.
  cardholder_statement String?

  /// Deadline for submitting evidence to dispute (for external disputes).
  evidence_deadline DateTime? @db.Timestamptz

  /// Whether additional evidence is required to resolve the dispute.
  evidence_required Boolean

  /// Timestamp when evidence was submitted to resolve the dispute.
  evidence_submitted_at DateTime? @db.Timestamptz

  /// Type of resolution: full_refund, partial_refund, no_action,
  /// evidence_accepted, evidence_rejected, settled.
  resolution_type String?

  /// Amount actually resolved/refunded in dispute.
  resolution_amount Float? @db.DoublePrecision

  /// Detailed notes about dispute resolution and outcome.
  resolution_notes String?

  /// Date when dispute was resolved.
  resolution_date DateTime? @db.Timestamptz

  /// Whether customer has been contacted about dispute status.
  customer_contacted Boolean

  /// Whether seller has been contacted for evidence or response.
  seller_contacted Boolean

  /// Deadline for seller response to dispute inquiry.
  response_deadline DateTime? @db.Timestamptz

  /// Seller's response or explanation regarding the dispute.
  seller_response String?

  /// Internal notes for dispute handling team and legal review.
  internal_notes String?

  /// Financial impact assessment: positive, negative, neutral (for platform
  /// accounting).
  financial_impact String

  /// JSON metadata for additional dispute information (evidence files,
  /// correspondence, etc.).
  metadata String? @db.VarChar(80000)

  /// Timestamp when dispute was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when dispute record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  transaction ecommerce_mall_transactions @relation(fields: [ecommerce_mall_transaction_id], references: [id], onDelete: Cascade)
  order ecommerce_mall_orders @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  customer ecommerce_mall_customers @relation(fields: [ecommerce_mall_customer_id], references: [id], onDelete: Cascade)
  seller ecommerce_mall_sellers @relation(fields: [ecommerce_mall_seller_id], references: [id], onDelete: Cascade)
  assignedTo ecommerce_mall_administrators? @relation(fields: [ecommerce_mall_administrator_id], references: [id], onDelete: Cascade)

  ecommerce_mall_payment_audits ecommerce_mall_payment_audits[]

  @@index([ecommerce_mall_order_id])
  @@index([ecommerce_mall_administrator_id])

  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_transaction_id, dispute_type], map: "ecommerce_mall_disputes_ecommerce_mall_transaction_id__b60b71b6")
  @@index([ecommerce_mall_customer_id, status])
  @@index([ecommerce_mall_seller_id, status])
  @@index([status, business_status])
  @@index([dispute_type, priority])
  @@index([is_external, status])
  @@index([created_at])
  @@index([reason_details(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([cardholder_statement(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([seller_response(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([resolution_notes(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([internal_notes(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System audit log for all payment-related actions and administrative
/// changes. Records comprehensive audit trail for compliance, security
/// monitoring, and financial reconciliation. Tracks administrative actions,
/// system changes, security events, and regulatory compliance activities
/// with detailed logging for forensic analysis and audit requirements.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_payment_audits {
